import java.util.ArrayList;


public class Almacen {
	private ArrayList<Maquina> maquinas;
	private float ingresos;

	public Almacen() {
		maquinas = new ArrayList<Maquina>();
		ingresos = 0;
	}
	
	public void registrarMaquina(Maquina maquina) {
		if (buscarMaquina(maquina.getCodigo()) == null){
			maquinas.add(maquina);
		}
	}
	
	public Maquina buscarMaquina(String codigo) {
		for (Maquina maquina : maquinas){
			if (maquina.getCodigo().equals(codigo)){

				return maquina;
			}
		}

		return null;
	}
	
	public void mostrarInventario() {
		for (Maquina maquina : maquinas){
			System.out.println("Tipo: " + maquina.getTipo());
        	System.out.println("Código: " + maquina.getCodigo());
        	System.out.println("Marca: " + maquina.getMarca());
        	System.out.println("Modelo: " + maquina.getModelo());
        	System.out.println("Tarifa diaria: Q" + maquina.getTarifa());
        	System.out.println("Disponible: " + maquina.getDisponible());
        	maquina.mostrarCaracteristicas();
			System.out.println();
		}
	}
	
	public void cotizar(String codigo, int dias) {
		Maquina maquina = buscarMaquina(codigo);

		if(maquina != null) {
			System.out.println("Tipo: " + maquina.getTipo());
        	System.out.println("Código: " + maquina.getCodigo());
        	System.out.println("Marca: " + maquina.getMarca());
        	System.out.println("Modelo: " + maquina.getModelo());
        	System.out.println("Tarifa diaria: Q" + maquina.getTarifa());
        	System.out.println("Disponible: " + maquina.getDisponible());
			maquina.mostrarCaracteristicas();

			float total = maquina.Cotizacion(dias);
			System.out.println("Costo total: Q" + total);

		}

		else{
			System.out.println("Máquina no encontrada.");
		}
	}
	
	public void alquilar(String codigo, int dias, boolean confirmar) {
    	Maquina maquina = buscarMaquina(codigo);
    	if (maquina != null) {
			if (maquina.getDisponible()) {
            	float total = maquina.Cotizacion(dias);
            	System.out.println("Costo total: Q" + total);

            	if (confirmar) {
                	maquina.setDisponible(false);
                	ingresos += total;
                	System.out.println("Alquiler realizado correctamente.");
				} else {
                	System.out.println("Alquiler cancelado.");
            	}
        	} 
			else {
            System.out.println("La máquina ya se encuentra alquilada.");
        	}

    	} 
		else {
        System.out.println("Máquina no encontrada.");
    	}
	}
	
	public void devolver(String codigo) {
		Maquina maquina = buscarMaquina(codigo);

		if (maquina != null){
			if(!maquina.getDisponible()){
				maquina.setDisponible(true);
				System.out.println("Máquina devuelta.");
			}
			else {
				System.out.println("La máquina ya se encuentra disponible.");
			}
		}
		else{
			System.out.println("Máquina no encontrada.");
		}
	}
	
	public int cantidadMaquinas() {
		return maquinas.size();
	}
	
	public int cantidadDisponibles() {
		int cantidad = 0;
		for(Maquina maquina: maquinas){
			if(maquina.getDisponible()){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int cantidadPoporopos() {
		int cantidad = 0;
		for(Maquina maquina: maquinas){
			if(maquina.getTipo().equals("Poporopos")){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int cantidadAlgodon() {
		int cantidad = 0;
		for(Maquina maquina: maquinas){
			if(maquina.getTipo().equals("Algodon")){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int cantidadChocolate() {
		int cantidad = 0;
		for(Maquina maquina: maquinas){
			if(maquina.getTipo().equals("Chocolate")){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int alquiladasPoporopos() {
		int cantidad = 0;
		for(Maquina maquina : maquinas){
			if(maquina.getTipo().equals("Poporopos") && !maquina.getDisponible()){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int alquiladasAlgodon() {
		int cantidad = 0;
		for(Maquina maquina : maquinas){
			if(maquina.getTipo().equals("Algodon") && !maquina.getDisponible()){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public int alquiladasChocolate() {
		int cantidad = 0;
		for(Maquina maquina : maquinas){
			if(maquina.getTipo().equals("Chocolate") && !maquina.getDisponible()){
				cantidad++;
			}
		}
		return cantidad;
	}
	
	public float getIngresos() {
		return ingresos;
	}
}
